import { useState } from "react";
import type { CSSProperties } from "react";

export type Signal = "stop" | "ready" | "go";
export type Props = { onChange: (signal: Signal) => void };

const tokens = {
  colors: { panel: "#eef4ff", text: "#17345c" },
  spacing: { panelPadding: 12, controlGap: 6 },
};

const panelStyle: CSSProperties = {
  background: tokens.colors.panel,
  color: tokens.colors.text,
  padding: tokens.spacing.panelPadding,
  gap: tokens.spacing.controlGap,
  display: "grid",
};

const followingSignal: Record<Signal, Signal> = {
  stop: "ready",
  ready: "go",
  go: "stop",
};

export function Component({ onChange }: Props) {
  const [signal, setSignal] = useState<Signal>("stop");

  function next() {
    const value = followingSignal[signal];
    setSignal(value);
    onChange(value);
  }

  function reset() {
    if (signal === "stop") return;
    setSignal("stop");
    onChange("stop");
  }

  return (
    <div data-testid="panel" style={panelStyle}>
      <output aria-label="Signal">{signal}</output>
      <button type="button" onClick={next}>Next</button>
      <button type="button" onClick={reset} disabled={signal === "stop"}>
        Reset
      </button>
    </div>
  );
}
